  const warmups=[
    {title:'Gentle & grounded',tone:'Ease into your voice',color:'#ff477e',items:[['Breath release','Gentle, unforced exhale on “sss”. Keep shoulders soft.','4 min'],['Lip trill glide','Glide through a small, comfortable range on a relaxed lip trill.','5 min'],['Humming resonance','Hum lightly, noticing vibration around the lips and face.','5 min'],['Five-note patterns','Sing short five-note patterns; move only while the voice feels easy.','6 min'],['Connected vowels','Carry a gentle “oo–oh–ah” across a few comfortable notes.','5 min'],['Cool-down check-in','Return to a quiet hum and notice how the voice feels.','5 min']]},
    {title:'Agile & expressive',tone:'Find ease through movement',color:'#e5c98f',items:[['Breath and posture','Release jaw and shoulders; breathe quietly without lifting the chest.','4 min'],['Siren glides','Make a light “ng” glide from low to high and back, without pushing.','5 min'],['Short runs','Practice three-note turns slowly, then let them become a little quicker.','6 min'],['Vowel flexibility','Repeat a comfortable note on “ee–eh–ah–oh–oo” with a free jaw.','5 min'],['Dynamic arcs','Grow a soft “mmm” slightly louder and return without squeezing.','5 min'],['Easy phrase','Sing a short phrase you know well, then finish with a gentle hum.','5 min']]},
    {title:'Resonance & color',tone:'Shape a sound that feels like you',color:'#c5a7f5',items:[['Quiet reset','Let out a few easy breaths; release the tongue and jaw.','4 min'],['Resonant hum','Hum a comfortable pitch softly; explore a warm, buzzy sensation.','5 min'],['Siren into vowel','Glide on “ng”, then open to “ah” while keeping the sound light.','5 min'],['Vowel color','Sing a familiar note on different vowels; keep the throat comfortable.','6 min'],['Honey tone study','Try a gentle, speech-like phrase with clear words and easy resonance.','5 min'],['Personal phrase','Shape one lyric with a chosen emotion, then cool down with humming.','5 min']]}
  ];
  const exercises=[
    {title:'Siren glides',tag:'RANGE · GENTLE',icon:'⌁',desc:'A smooth glide can help you notice transitions without forcing the voice.',steps:'Use a soft “ng” or lip trill. Start in an easy middle pitch and glide only as far as remains comfortable. Keep the volume light. Do three or four slow glides, resting between them. Stop if you feel pain or persistent strain.'},
    {title:'Disney-style storytelling',tag:'EXPRESSION · CHARACTER',icon:'✧',desc:'Explore a clear, buoyant, story-led delivery while keeping your own voice comfortable.',steps:'Choose one short lyric. Speak it as if sharing a surprising story, then sing it with the same intention. Try a brighter vowel and clear consonants at a moderate volume. This is an expressive style prompt, not a claim to reproduce a specific performer.'},
    {title:'Honey-vocal ease',tag:'RESONANCE · TONE',icon:'◌',desc:'Explore a warm, speech-like tone with relaxed articulation and steady breath.',steps:'Begin with an easy “mmm”. Open into “mum” or a short phrase while preserving the gentle resonance. Keep the sound conversational and avoid artificially lowering the pitch. Pause if the throat feels pressed.'},
    {title:'Pitch steps',tag:'PITCH · ACCURACY',icon:'↗',desc:'Build awareness of the space between comfortable notes.',steps:'Use the live pitch monitor with a drone. Sing one comfortable note, pause, then move up a small step and return. Keep volume moderate. Compare what you hear with the display; the estimate can be imperfect.'},
    {title:'Phrase shaping',tag:'MUSICALITY · TIMING',icon:'〰',desc:'Practice a musical phrase with deliberate breath, timing, and release.',steps:'Pick a phrase of four to eight seconds. Speak the text in rhythm, then sing it softly. Notice where you breathe, which word carries the meaning, and whether the final note releases freely.'},
    {title:'Easy register map',tag:'RANGE · AWARENESS',icon:'⌖',desc:'Notice where your voice feels different without treating range as a target.',steps:'Hum gently through a small range and note where the sensation changes. There is no need to label a register or reach a high or low note. Keep the sound easy and use short attempts with rest.'},
    {title:'Breath phrase planner',tag:'BREATH · CONTROL',icon:'↗',desc:'Find a comfortable place to breathe before a lyric phrase begins.',steps:'Speak a short lyric naturally. Mark a place where a quiet breath feels easy, then sing the phrase once at a moderate volume. Try not to hold or gulp the breath. Shorten the phrase if you feel you are running out of air.'},
    {title:'Consonant sparkle',tag:'EXPRESSION · CLARITY',icon:'✧',desc:'Make words clear while keeping the jaw loose and the sound easy.',steps:'Choose one line and speak it slowly, letting the consonants be crisp but light. Sing it on a comfortable melody, then repeat with the same clear words and a relaxed jaw. Avoid punching or over-articulating.'},
    {title:'Five-note pathways',tag:'PITCH · AGILITY',icon:'⌁',desc:'Explore a small melodic pattern at a pace that stays relaxed.',steps:'Choose five neighboring comfortable notes, or use a keyboard or drone as a guide. Sing up and down slowly on “loo”. Pause between patterns. Keep the range modest; skip any note that feels strained.'},
    {title:'Soft-to-strong arc',tag:'DYNAMICS · CONTROL',icon:'〰',desc:'Shape a gentle change in volume without pushing for more power.',steps:'On a comfortable note, begin quietly, grow only a little louder, and return to quiet over a few seconds. Keep the throat soft and stop before the sound feels effortful. Repeat two or three times with a rest.'},
    {title:'Vowel color carousel',tag:'RESONANCE · TONE',icon:'◌',desc:'Explore how a vowel changes the color of the same comfortable note.',steps:'Hold an easy note at a gentle volume. Slowly move through “oo, oh, ah, eh, ee” without changing the pitch on purpose. Notice the different sensations. Keep the jaw comfortable and do not chase a particular tone.'},
    {title:'Rhythm echo',tag:'MUSICALITY · TIMING',icon:'♫',desc:'Build rhythmic confidence with a spoken-and-sung echo.',steps:'Tap a simple, steady pulse. Speak a short lyric to that pulse, pause, then sing it with the same rhythm on an easy melody. Keep the pulse relaxed and let the phrase breathe.'},
    {title:'Lyric intention switch',tag:'EXPRESSION · STORY',icon:'✦',desc:'Try two different emotional intentions while staying in your natural voice.',steps:'Choose one lyric and speak it once as a secret, then as a warm welcome. Sing it with each intention at a comfortable volume. Notice what changes in timing and emphasis. This is an exploration, not an imitation exercise.'},
    {title:'Hum-to-phrase bridge',tag:'WARM-UP · RESONANCE',icon:'◉',desc:'Move from a gentle hum into words while keeping the sound easy.',steps:'Hum a comfortable pitch for a few seconds. Open into “mum” and then a short phrase, staying at a conversational volume. Reset with a breath between attempts. Stop if the throat feels pressed.'},
    {title:'Siren landing notes',tag:'RANGE · GENTLE',icon:'⌁',desc:'Add a calm landing point to a small, comfortable siren glide.',steps:'Make a gentle “ng” glide over a small range and settle on an easy middle note. Hold that note briefly, then release. Keep the glide light; avoid pushing to the top or bottom of your range.'},
    {title:'Storybook phrase',tag:'EXPRESSION · CHARACTER',icon:'✧',desc:'Give one lyric a vivid story with clear words and a buoyant delivery.',steps:'Speak a short lyric as if telling a friend a surprising story. Sing it with clear consonants and a bright, comfortable tone. Keep your own natural voice and moderate volume; no need to copy a singer or character.'},
    {title:'Easy cooldown',tag:'RECOVERY · GENTLE',icon:'❋',desc:'Finish practice with a quiet reset and a check-in with your voice.',steps:'Take a quiet breath and hum softly in a comfortable middle range for a few moments. Let the sound fade without forcing it. Notice how your voice feels. Rest if you feel tired or uncomfortable.'}
  ];
