  function renderStreakCalendar(){const first=new Date(rewardCalendarMonth.getFullYear(),rewardCalendarMonth.getMonth(),1),year=first.getFullYear(),month=first.getMonth(),days=new Date(year,month+1,0).getDate(),offset=(first.getDay()+6)%7,done=new Set(rewardsState.practiceDates),today=VocalRewards.dateKey(new Date());$('#streak-month-label').textContent=first.toLocaleDateString(undefined,{month:'long',year:'numeric'});let html='';for(let i=0;i<offset;i++)html+='<span class="streak-day empty"></span>';for(let d=1;d<=days;d++){const key=VocalRewards.dateKey(new Date(year,month,d,12)),classes=['streak-day',done.has(key)?'completed':'',key===today?'today':''].filter(Boolean).join(' ');html+='<span class="'+classes+'"'+(done.has(key)?' title="Practice completed"':'')+'>'+d+(done.has(key)?'<i>✦</i>':'')+'</span>'}$('#streak-calendar-grid').innerHTML=html}
  function renderRewards(){const stats=VocalRewards.streakStats(rewardsState.practiceDates,new Date(),rewardsState.longestStreak),next=stats.nextMilestone;$('#current-streak').textContent=stats.current;$('#longest-streak').textContent=stats.longest;$('#next-streak-milestone').textContent=next?next.days+' days':'Hall of Fame';$('#next-streak-reward').textContent=next?(next.cards?next.cards+' scratch '+(next.cards===1?'card':'cards')+' at this milestone':next.rarity+' reward'):'Every milestone reached';$('#star-coin-count').textContent=rewardsState.starCoins;renderStreakCalendar();$('#streak-milestone-list').innerHTML=VocalRewards.MILESTONES.map(m=>{const claimed=rewardsState.claimedMilestones.includes(m.days),current=stats.current>=m.days,status=claimed?'Earned':current?'Milestone reached':'Practice '+m.days+' consecutive days',reward=m.cards?m.cards+' scratch '+(m.cards===1?'card':'cards'):m.rarity+' reward';return'<div class="streak-milestone '+(claimed?'earned':'')+'"><span class="milestone-icon">'+(claimed?'✦':'·')+'</span><div><b>'+m.days+' days</b><small>'+reward+'</small></div><em>'+status+'</em></div>'}).join('');const pending=rewardsState.cards.filter(c=>c.status==='pending').length;$('#scratch-card-count').textContent=pending+' '+(pending===1?'card':'cards')+' ready · '+rewardsState.cards.length+' earned';$('#scratch-start').disabled=pending===0;$('#scratch-start').textContent=pending?'Scratch a card':'No cards ready';$('#reward-collection-count').textContent=rewardsState.collection.length+' '+(rewardsState.collection.length===1?'reward':'rewards');const host=$('#reward-collection-list');host.innerHTML=rewardsState.collection.length?rewardsState.collection.map(r=>'<div class="collected-reward"><span class="rarity-mark rarity-'+r.rarity.toLowerCase().replace(/[^a-z]+/g,'-')+'">✦</span><div><b>'+r.name+'</b><small>'+r.description+'</small><small>'+r.rarity+' · '+(r.source==='scratch-card'?'Scratch card':'Streak milestone '+r.milestone)+' · '+r.earnedAt+'</small></div></div>').join(''):'<div class="reward-empty">Your rewards will appear here as you practice and reach milestones.</div>'}
  function drawScratchSurface(){const canvas=$('#scratch-surface');if(!canvas||canvas.hidden)return;const rect=canvas.getBoundingClientRect();if(rect.width<10)return;const dpr=window.devicePixelRatio||1,w=rect.width,h=180;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);const g=c.createLinearGradient(0,0,w,h);g.addColorStop(0,themeColor('--scratch-a','#bc2853'));g.addColorStop(.45,themeColor('--scratch-b','#eadde3'));g.addColorStop(1,themeColor('--scratch-c','#8a2347'));c.fillStyle=g;c.fillRect(0,0,w,h);c.strokeStyle='#ffffff99';c.lineWidth=1;for(let x=-h;x<w;x+=24){c.beginPath();c.moveTo(x,0);c.lineTo(x+h,h);c.stroke()}c.fillStyle=themeColor('--scratch-ink','#382b46');c.textAlign='center';c.textBaseline='middle';c.font='700 17px Nunito,Arial,sans-serif';c.fillText('✦  SCRATCH TO REVEAL  ✦',w/2,h/2-7);c.font='12px Nunito,Arial,sans-serif';c.fillText('Your practice earned this reward',w/2,h/2+20);c.globalCompositeOperation='source-over'}
