  function revealScratchCard(){if(!activeScratchId)return;const result=VocalRewards.scratchCard(rewardsState,activeScratchId);if(result.duplicate)return;rewardsState=result.state;persistRewards();activeScratchId=null;scratchPointerDown=false;$('#scratch-surface').hidden=true;$('#scratch-reveal-button').hidden=true;const content=$('#scratch-reveal-content'),r=result.reward;content.innerHTML='<span class="eyebrow">'+r.rarity.toUpperCase()+' REWARD</span><h3>'+r.name+'</h3><p>'+r.description+'</p>';content.className='scratch-reveal-content reward-revealed rarity-'+r.rarity.toLowerCase().replace(/[^a-z]+/g,'-');content.hidden=false;$('#scratch-prompt').textContent='Reward revealed and added to your collection.';renderRewards()}
  function scratchPercent(){const canvas=$('#scratch-surface'),c=canvas.getContext('2d'),data=c.getImageData(0,0,canvas.width,canvas.height).data;let transparent=0,total=0;for(let i=3;i<data.length;i+=16){total++;if(data[i]<24)transparent++}return total?transparent/total:0}
